allBodies = []
def hideBody(b):
    try:
        ViewHelper.SetObjectVisibility(Selection.Create(b), VisibilityType.Hide, False, False)
        allBodies.append(b)
    except: pass

def createSquareArrayHoles(cx, cy, cz, nx, ny, nz, nSide, rHole, spacing, tLen):
    createdBodies = []
    if nSide <= 0: return createdBodies
    nVec = Vector.Create(nx, ny, nz)
    if nVec.Magnitude <= 1e-12: return createdBodies
    nVec = Vector.Create(nVec.X/nVec.Magnitude, nVec.Y/nVec.Magnitude, nVec.Z/nVec.Magnitude)
    if abs(nVec.X) > 0.9:
        uVec = Vector.Create(0, 1, 0)
    else:
        uC = Vector.Cross(nVec, Vector.Create(1, 0, 0))
        uVec = Vector.Create(uC.X/uC.Magnitude, uC.Y/uC.Magnitude, uC.Z/uC.Magnitude)
    vC = Vector.Cross(nVec, uVec)
    vVec = Vector.Create(vC.X/vC.Magnitude, vC.Y/vC.Magnitude, vC.Z/vC.Magnitude)
    offsetU = - (nSide - 1) / 2.0 * spacing
    offsetV = - (nSide - 1) / 2.0 * spacing
    for i in range(int(nSide)):
        for j in range(int(nSide)):
            dx = offsetU + i * spacing
            dy = offsetV + j * spacing
            pCx = cx + uVec.X * dx + vVec.X * dy
            pCy = cy + uVec.Y * dx + vVec.Y * dy
            pCz = cz + uVec.Z * dx + vVec.Z * dy
            p1X = pCx - nVec.X * (tLen / 2.0)
            p1Y = pCy - nVec.Y * (tLen / 2.0)
            p1Z = pCz - nVec.Z * (tLen / 2.0)
            p2X = pCx + nVec.X * (tLen / 2.0)
            p2Y = pCy + nVec.Y * (tLen / 2.0)
            p2Z = pCz + nVec.Z * (tLen / 2.0)
            p3X = p2X + uVec.X * rHole
            p3Y = p2Y + uVec.Y * rHole
            p3Z = p2Z + uVec.Z * rHole
            try:
                res = CylinderBody.Create(Point.Create(MM(p1X), MM(p1Y), MM(p1Z)), Point.Create(MM(p2X), MM(p2Y), MM(p2Z)), Point.Create(MM(p3X), MM(p3Y), MM(p3Z)), ExtrudeType.ForceIndependent)
                for b in res.CreatedBodies: createdBodies.append(b)
            except: pass
    return createdBodies

